mapper.select:
select
    id, object_type as objectType, old_id as oldId, old_name as oldName,
    new_id as newId, new_name as newName, old_biz_line as oldBizLine, new_biz_line as newBizLine,
    portal_id as portalId, is_reused as isReused, created_by as createdBy,
    date_format(created_time , '%Y-%m-%d %H:%i:%s') as createdTime
from ssm_migrate_bizsplit_mapping
where object_type = #{objectType}
  and old_id = #{oldId}
  and new_biz_line = #{newBizLine}
limit 1

select pkid, shadow_cfg_id as shadowCfgId, old_view_id as viewId, old_tpl_id as tplId, cfg_id as cfgId, source_businessline as sourceBusinessline, target_businessline as targetBusinessline, old_field_id as oldFieldId, old_field_code as oldFieldCode, old_field_title as oldFieldTitle, new_field_id as newFieldId, new_field_code as newFieldCode, new_field_title as newFieldTitle from ssm_metric_expansion_field_mapping where source_businessline = #{sourceBusinessline} and target_businessline = #{targetBusinessline}
and old_tpl_id = #{tplId}
and old_view_id = #{viewId}
